interface SteppedPoints {
    points: number[]
    /**
     * `null` if no `stackedOnPoints` is given.
     */
    stackedOnPoints: number[]
}

/**
 * Generate the points of a step line.
 *
 * `stackedOnPoints` (the base line of the area of the series, see #20092) is
 * converted together with `points` on purpose: both arrays must stay index
 * aligned and share the very same progression on the base axis, otherwise
 * `ECPolygon` (which walks `points` forwards and `stackedOnPoints` backwards
 * by index) would build a skewed area.
 *
 * Null points are dropped **only** when `connectNulls` is enabled, so that the
 * gaps of a step line are not bridged when the user didn't ask for it. The null
 * state is always determined from `points`, since the base line of the area is
 * always defined (it falls back to the value origin) and therefore can't tell
 * where the gaps are.
 */
function turnPointsIntoStep(
    points: ArrayLike<number>,
    stackedOnPoints: ArrayLike<number>,
    coordSys: Cartesian2D | Polar,
    stepTurnAt: 'start' | 'end' | 'middle',
    connectNulls: boolean
): SteppedPoints {
    const baseAxis = coordSys.getBaseAxis();
    const baseIndex = baseAxis.dim === 'x' || baseAxis.dim === 'radius' ? 0 : 1;
    const hasStackedOn = !!stackedOnPoints;

    if (connectNulls) {
        // Bridge the null gaps by simply removing the null points. The same
        // indices have to be removed from the base line of the area.
        const filteredPoints: number[] = [];
        const filteredStackedOnPoints: number[] = hasStackedOn ? [] : null;
        for (let i = 0; i < points.length; i += 2) {
            if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
                filteredPoints.push(points[i], points[i + 1]);
                if (hasStackedOn) {
                    filteredStackedOnPoints.push(stackedOnPoints[i], stackedOnPoints[i + 1]);
                }
            }
        }
        points = filteredPoints;
        stackedOnPoints = filteredStackedOnPoints;
    }

    const stepPt: number[] = [];
    const stepPt2: number[] = [];
    const pt: number[] = [];
    const nextPt: number[] = [];

    function toStepPoints(rawPoints: ArrayLike<number>): number[] {
        const stepPoints: number[] = [];
        let i = 0;
        for (i = 0; i < rawPoints.length - 2; i += 2) {
            nextPt[0] = rawPoints[i + 2];
            nextPt[1] = rawPoints[i + 3];
            pt[0] = rawPoints[i];
            pt[1] = rawPoints[i + 1];
            stepPoints.push(pt[0], pt[1]);

            switch (stepTurnAt) {
                case 'end':
                    stepPt[baseIndex] = nextPt[baseIndex];
                    stepPt[1 - baseIndex] = pt[1 - baseIndex];
                    stepPoints.push(stepPt[0], stepPt[1]);
                    break;
                case 'middle':
                    const middle = (pt[baseIndex] + nextPt[baseIndex]) / 2;
                    stepPt[baseIndex] = stepPt2[baseIndex] = middle;
                    stepPt[1 - baseIndex] = pt[1 - baseIndex];
                    stepPt2[1 - baseIndex] = nextPt[1 - baseIndex];
                    stepPoints.push(stepPt[0], stepPt[1]);
                    stepPoints.push(stepPt2[0], stepPt2[1]);
                    break;
                default:
                    // default is start
                    stepPt[baseIndex] = pt[baseIndex];
                    stepPt[1 - baseIndex] = nextPt[1 - baseIndex];
                    stepPoints.push(stepPt[0], stepPt[1]);
            }
        }
        // Last points
        if (rawPoints.length >= 2) {
            stepPoints.push(rawPoints[i], rawPoints[i + 1]);
        }
        return stepPoints;
    }

    return {
        points: toStepPoints(points),
        stackedOnPoints: hasStackedOn ? toStepPoints(stackedOnPoints) : null
    };
}

/**
 * Points that are actually used by `ECPolyline` / `ECPolygon`. They are the raw
 * layout points unless the series is a step line.
 */
function preparePolyPoints(
    points: ArrayLike<number>,
    stackedOnPoints: ArrayLike<number>,
    coordSys: Cartesian2D | Polar,
    step: LineSeriesOption['step'],
    connectNulls: boolean
): SteppedPoints {
    // TODO If stacked series is not step
    return step
        ? turnPointsIntoStep(points, stackedOnPoints, coordSys, step, connectNulls)
        : { points: points as number[], stackedOnPoints: stackedOnPoints as number[] };
}

